template <typename UnionPtrType>
WebcamIdPtr WebcamId::Clone() const {
  switch (tag_) {
    case Tag::kDeviceId:
      return NewDeviceId(
          mojo::Clone(*data_.device_id));
    case Tag::kDevPath:
      return NewDevPath(
          mojo::Clone(*data_.dev_path));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, WebcamId>::value>::type*>
bool WebcamId::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kDeviceId:
      return mojo::Equals(*(data_.device_id), *(other.data_.device_id));
    case Tag::kDevPath:
      return mojo::Equals(*(data_.dev_path), *(other.data_.dev_path));
  }

  return false;
}
template <typename UnionPtrType>
CtrlTypePtr CtrlType::Clone() const {
  switch (tag_) {
    case Tag::kMappingCtrl:
      return NewMappingCtrl(
          mojo::Clone(*data_.mapping_ctrl));
    case Tag::kQueryCtrl:
      return NewQueryCtrl(
          mojo::Clone(*data_.query_ctrl));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, CtrlType>::value>::type*>
bool CtrlType::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kMappingCtrl:
      return mojo::Equals(*(data_.mapping_ctrl), *(other.data_.mapping_ctrl));
    case Tag::kQueryCtrl:
      return mojo::Equals(*(data_.query_ctrl), *(other.data_.query_ctrl));
  }

  return false;
}
